package com.collabcase.runtime.sync;

import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import com.collabcase.runtime.app.*;
import com.collabcase.runtime.dto.RuntimeDtos.*;
import com.collabcase.runtime.record.*;

@Service
public class RuntimeSyncService {
    private final RuntimeAppService apps;private final RuntimeRecordRepository records;private final RuntimeMutationRepository mutations;private final RuntimeDefinitionValidator validator;private final RuntimeVersionService versions;
    public RuntimeSyncService(RuntimeAppService apps,RuntimeRecordRepository records,RuntimeMutationRepository mutations,RuntimeDefinitionValidator validator,RuntimeVersionService versions){this.apps=apps;this.records=records;this.mutations=mutations;this.validator=validator;this.versions=versions;}
    @Transactional public SyncResponse sync(UUID appId,String token,SyncRequest request){RuntimeApp app=apps.authenticate(appId,token);List<Accepted> accepted=new ArrayList<>();List<Conflict> conflicts=new ArrayList<>();for(SyncMutation mutation:safe(request.mutations())){if(mutations.existsByAppIdAndMutationId(appId,mutation.mutationId())){accepted.add(new Accepted(mutation.mutationId(),mutation.recordId(),0,0,true));continue;}process(app,mutation,accepted,conflicts);if(conflicts.stream().noneMatch(c->c.mutationId().equals(mutation.mutationId()))){RuntimeMutation processed=new RuntimeMutation();processed.setApp(app);processed.setMutationId(mutation.mutationId());mutations.save(processed);}}List<RecordResponse> changes=records.findByAppIdAndSyncVersionGreaterThanOrderBySyncVersionAsc(appId,request.lastSyncVersion()).stream().map(this::response).toList();long cursor=changes.isEmpty()?request.lastSyncVersion():changes.getLast().syncVersion();return new SyncResponse(accepted,conflicts,changes,cursor);}
    private void process(RuntimeApp app,SyncMutation mutation,List<Accepted> accepted,List<Conflict> conflicts){validator.validate(app,mutation.entityType(),mutation.data()==null?Map.of():mutation.data());Optional<RuntimeRecord> existing=records.findLockedByAppIdAndEntityTypeAndRecordId(app.getId(),mutation.entityType(),mutation.recordId());if(existing.isEmpty()){if(mutation.baseVersion()!=0||"DELETE".equalsIgnoreCase(mutation.operation())){conflicts.add(new Conflict(mutation.mutationId(),mutation.recordId(),0,Map.of(),true));return;}RuntimeRecord record=new RuntimeRecord();record.setApp(app);record.setEntityType(mutation.entityType());record.setRecordId(mutation.recordId()==null?UUID.randomUUID():mutation.recordId());record.setData(copy(mutation.data()));record.setVersion(1);record.setSyncVersion(versions.next());records.saveAndFlush(record);accepted.add(new Accepted(mutation.mutationId(),record.getRecordId(),record.getVersion(),record.getSyncVersion(),false));return;}RuntimeRecord record=existing.get();if(record.getVersion()!=mutation.baseVersion()){conflicts.add(new Conflict(mutation.mutationId(),record.getRecordId(),record.getVersion(),record.getData(),record.isDeleted()));return;}if("DELETE".equalsIgnoreCase(mutation.operation()))record.setDeleted(true);else{record.setData(copy(mutation.data()));record.setDeleted(false);}record.setVersion(record.getVersion()+1);record.setSyncVersion(versions.next());records.saveAndFlush(record);accepted.add(new Accepted(mutation.mutationId(),record.getRecordId(),record.getVersion(),record.getSyncVersion(),false));}
    private RecordResponse response(RuntimeRecord r){return new RecordResponse(r.getRecordId(),r.getEntityType(),r.getVersion(),r.getSyncVersion(),r.getData(),r.isDeleted(),r.getCreatedAt(),r.getUpdatedAt());}
    private Map<String,Object> copy(Map<String,Object> data){return data==null?Map.of():new LinkedHashMap<>(data);}private List<SyncMutation> safe(List<SyncMutation> value){return value==null?List.of():value;}
}
